def build_output(n, edges, rounds, rep):
    classes, summary = build_evidence(n, edges, rounds, rep)
    R = rep["R"]
    rounds_out = []
    for r in range(R):
        started = rep["source_started"][r]
        sp = rep["source_proof"][r]
        if sp is None:
            sp_list = []
        else:
            sp_list = sorted(sp)
        rounds_out.append({
            "id": r,
            "started": bool(started),
            "source_final_us": rep["source_final_us"][r] if started else None,
            "source_complete": (rep["source_complete"][r]
                                if started else None),
            "host_delivery_us": rep["host_delivery_us"][r],
            "source_proof": sp_list,
        })
    return {
        "rounds": rounds_out,
        "metrics": rep["metrics"],
        "classes": classes,
        "summary": summary,
    }


def main():
    sys.setrecursionlimit(10000)
    raw = sys.stdin.buffer.read()
    try:
        obj = parse_input(raw)
        n, cap, edges, rounds = validate(obj)
    except Invalid:
        sys.stdout.write(json.dumps({"error": "invalid-input"}))
        sys.stdout.write("\n")
        raise SystemExit(2)
    rep = replay(n, cap, edges, rounds)
    out = build_output(n, edges, rounds, rep)
    sys.stdout.write(json.dumps(out))
    sys.stdout.write("\n")
    raise SystemExit(0)


if __name__ == "__main__":
    main()
